SET ANSI_NULLS ON; SET QUOTED_IDENTIFIER ON; SET ANSI_PADDING ON; SET ANSI_WARNINGS ON; SET ARITHABORT ON; SET CONCAT_NULL_YIELDS_NULL ON; SET NUMERIC_ROUNDABORT OFF; SET XACT_ABORT ON; SET NOCOUNT ON;
BEGIN TRAN;
IF OBJECT_ID('dbo.Countries') IS NULL CREATE TABLE dbo.Countries(CountryId uniqueidentifier NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,CountryCode nvarchar(20) NOT NULL,CountryNameEn nvarchar(100) NOT NULL,CountryNameAr nvarchar(100) NULL,IsoCode nvarchar(3) NULL,IsActive bit NOT NULL DEFAULT 1,IsDeleted bit NOT NULL DEFAULT 0,CreatedTime datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CreatedBy nvarchar(100) NULL,ModifiedTime datetime2 NULL,ModifiedBy nvarchar(100) NULL,DeletedTime datetime2 NULL,DeletedBy nvarchar(100) NULL,CONSTRAINT UQ_Countries_Code UNIQUE(CountryCode));
IF OBJECT_ID('dbo.Banks') IS NULL CREATE TABLE dbo.Banks(BankId uniqueidentifier NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,BankCode nvarchar(50) NOT NULL,BankNameEn nvarchar(200) NOT NULL,BankNameAr nvarchar(200) NULL,ShortName nvarchar(100) NULL,IsActive bit NOT NULL DEFAULT 1,IsDeleted bit NOT NULL DEFAULT 0,CreatedTime datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CreatedBy nvarchar(100) NULL,ModifiedTime datetime2 NULL,ModifiedBy nvarchar(100) NULL,DeletedTime datetime2 NULL,DeletedBy nvarchar(100) NULL,CONSTRAINT UQ_Banks_Code UNIQUE(BankCode));
IF OBJECT_ID('dbo.Companies') IS NULL CREATE TABLE dbo.Companies(CompanyId uniqueidentifier NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,CompanyCode nvarchar(50) NOT NULL,CompanyNameEn nvarchar(200) NOT NULL,CompanyNameAr nvarchar(200) NULL,ShortName nvarchar(100) NULL,Notes nvarchar(500) NULL,IsActive bit NOT NULL DEFAULT 1,IsDeleted bit NOT NULL DEFAULT 0,CreatedTime datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CreatedBy nvarchar(100) NULL,ModifiedTime datetime2 NULL,ModifiedBy nvarchar(100) NULL,DeletedTime datetime2 NULL,DeletedBy nvarchar(100) NULL,CONSTRAINT UQ_Companies_Code UNIQUE(CompanyCode));
IF OBJECT_ID('dbo.Currencies') IS NULL CREATE TABLE dbo.Currencies(CurrencyId uniqueidentifier NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,CurrencyCode char(3) NOT NULL,CurrencyNameEn nvarchar(100) NOT NULL,CurrencyNameAr nvarchar(100) NULL,Symbol nvarchar(10) NULL,DecimalPlaces tinyint NOT NULL DEFAULT 2,IsActive bit NOT NULL DEFAULT 1,IsDeleted bit NOT NULL DEFAULT 0,CreatedTime datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CreatedBy nvarchar(100) NULL,ModifiedTime datetime2 NULL,ModifiedBy nvarchar(100) NULL,DeletedTime datetime2 NULL,DeletedBy nvarchar(100) NULL,CONSTRAINT UQ_Currencies_Code UNIQUE(CurrencyCode));
IF OBJECT_ID('dbo.Correspondents') IS NULL CREATE TABLE dbo.Correspondents(CorrespondentId uniqueidentifier NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,CorrespondentCode nvarchar(50) NOT NULL,CorrespondentNameEn nvarchar(200) NOT NULL,CorrespondentNameAr nvarchar(200) NULL,CountryId uniqueidentifier NULL REFERENCES dbo.Countries(CountryId),IsActive bit NOT NULL DEFAULT 1,IsDeleted bit NOT NULL DEFAULT 0,CreatedTime datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CreatedBy nvarchar(100) NULL,ModifiedTime datetime2 NULL,ModifiedBy nvarchar(100) NULL,DeletedTime datetime2 NULL,DeletedBy nvarchar(100) NULL,CONSTRAINT UQ_Correspondents_Code UNIQUE(CorrespondentCode));
IF OBJECT_ID('dbo.CorrespondentAccounts') IS NULL CREATE TABLE dbo.CorrespondentAccounts(CorrespondentAccountId uniqueidentifier NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,CorrespondentId uniqueidentifier NOT NULL REFERENCES dbo.Correspondents(CorrespondentId),CurrencyId uniqueidentifier NOT NULL REFERENCES dbo.Currencies(CurrencyId),AccountNumber nvarchar(100) NOT NULL,OpeningBalance decimal(19,4) NOT NULL DEFAULT 0,CurrentBalance decimal(19,4) NOT NULL DEFAULT 0,IsActive bit NOT NULL DEFAULT 1,IsDeleted bit NOT NULL DEFAULT 0,CreatedTime datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CreatedBy nvarchar(100) NULL,ModifiedTime datetime2 NULL,ModifiedBy nvarchar(100) NULL,DeletedTime datetime2 NULL,DeletedBy nvarchar(100) NULL,RowVersion rowversion,CONSTRAINT UQ_Accounts_Number UNIQUE(AccountNumber));
IF OBJECT_ID('dbo.Beneficiaries') IS NULL CREATE TABLE dbo.Beneficiaries(BeneficiaryId uniqueidentifier NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,BeneficiaryCode nvarchar(50) NOT NULL,BeneficiaryNameEn nvarchar(200) NOT NULL,BeneficiaryNameAr nvarchar(200) NULL,IsActive bit NOT NULL DEFAULT 1,IsDeleted bit NOT NULL DEFAULT 0,CreatedTime datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CreatedBy nvarchar(100) NULL,ModifiedTime datetime2 NULL,ModifiedBy nvarchar(100) NULL,DeletedTime datetime2 NULL,DeletedBy nvarchar(100) NULL,CONSTRAINT UQ_Beneficiaries_Code UNIQUE(BeneficiaryCode));
IF OBJECT_ID('dbo.ResourceTypes') IS NULL CREATE TABLE dbo.ResourceTypes(ResourceTypeId uniqueidentifier NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,ResourceTypeCode nvarchar(50) NOT NULL,ResourceTypeNameEn nvarchar(100) NOT NULL,ResourceTypeNameAr nvarchar(100) NULL,IsActive bit NOT NULL DEFAULT 1,IsDeleted bit NOT NULL DEFAULT 0,CreatedTime datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CreatedBy nvarchar(100) NULL,ModifiedTime datetime2 NULL,ModifiedBy nvarchar(100) NULL,DeletedTime datetime2 NULL,DeletedBy nvarchar(100) NULL,CONSTRAINT UQ_ResourceTypes_Code UNIQUE(ResourceTypeCode));
IF OBJECT_ID('dbo.OperationTypes') IS NULL CREATE TABLE dbo.OperationTypes(OperationTypeId uniqueidentifier NOT NULL PRIMARY KEY,OperationTypeCode nvarchar(50) NOT NULL UNIQUE,OperationTypeNameEn nvarchar(100) NOT NULL,IsActive bit NOT NULL DEFAULT 1);
IF OBJECT_ID('dbo.UsageTypes') IS NULL CREATE TABLE dbo.UsageTypes(UsageTypeId uniqueidentifier NOT NULL PRIMARY KEY,UsageTypeCode nvarchar(50) NOT NULL UNIQUE,UsageTypeNameEn nvarchar(100) NOT NULL,IsActive bit NOT NULL DEFAULT 1);
IF OBJECT_ID('dbo.Resources') IS NULL CREATE TABLE dbo.Resources(ResourceId uniqueidentifier NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,ResourceDate date NOT NULL,CorrespondentAccountId uniqueidentifier NOT NULL REFERENCES dbo.CorrespondentAccounts(CorrespondentAccountId),Amount decimal(19,4) NOT NULL,ResourceTypeId uniqueidentifier NOT NULL REFERENCES dbo.ResourceTypes(ResourceTypeId),Notes nvarchar(300) NULL,CreatedTime datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CreatedBy nvarchar(100) NULL,DeletedTime datetime2 NULL,DeletedBy nvarchar(100) NULL,CONSTRAINT CK_Resources_Amount CHECK(Amount>0));
IF OBJECT_ID('dbo.Transfers') IS NULL CREATE TABLE dbo.Transfers(TransferId uniqueidentifier NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,TransferDate datetime2 NOT NULL,CorrespondentAccountId uniqueidentifier NOT NULL REFERENCES dbo.CorrespondentAccounts(CorrespondentAccountId),BeneficiaryId uniqueidentifier NOT NULL REFERENCES dbo.Beneficiaries(BeneficiaryId),Amount decimal(19,4) NOT NULL,Purpose nvarchar(500) NOT NULL,ReferenceNo nvarchar(100) NOT NULL,OperationTypeId uniqueidentifier NULL REFERENCES dbo.OperationTypes(OperationTypeId),ResourceTypeId uniqueidentifier NULL REFERENCES dbo.ResourceTypes(ResourceTypeId),UsageTypeId uniqueidentifier NULL REFERENCES dbo.UsageTypes(UsageTypeId),BankId uniqueidentifier NULL REFERENCES dbo.Banks(BankId),TransferStatus nvarchar(20) NOT NULL DEFAULT 'Pending',CreatedTime datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CreatedBy nvarchar(100) NULL,ConfirmedTime datetime2 NULL,ConfirmedBy nvarchar(100) NULL,RejectedTime datetime2 NULL,RejectedBy nvarchar(100) NULL,RejectReason nvarchar(500) NULL,DeletedTime datetime2 NULL,DeletedBy nvarchar(100) NULL,CONSTRAINT CK_Transfers_Amount CHECK(Amount>0),CONSTRAINT CK_Transfers_Status CHECK(TransferStatus IN('Pending','Confirmed','Rejected')));
IF OBJECT_ID('dbo.Coverages') IS NULL CREATE TABLE dbo.Coverages(CoverageId uniqueidentifier NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,FromCorrespondentAccountId uniqueidentifier NOT NULL REFERENCES dbo.CorrespondentAccounts(CorrespondentAccountId),ToCorrespondentAccountId uniqueidentifier NOT NULL REFERENCES dbo.CorrespondentAccounts(CorrespondentAccountId),Amount decimal(19,4) NOT NULL,ReferenceNo nvarchar(100) NULL,Narration nvarchar(500) NULL,TransactionDate datetime2 NOT NULL,CreatedTime datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CreatedBy nvarchar(100) NULL,DeletedTime datetime2 NULL,DeletedBy nvarchar(100) NULL,CONSTRAINT CK_Coverages_Amount CHECK(Amount>0),CONSTRAINT CK_Coverages_Accounts CHECK(FromCorrespondentAccountId<>ToCorrespondentAccountId));
IF OBJECT_ID('dbo.Deals') IS NULL CREATE TABLE dbo.Deals(DealId uniqueidentifier NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,FromCorrespondentAccountId uniqueidentifier NOT NULL REFERENCES dbo.CorrespondentAccounts(CorrespondentAccountId),ToCorrespondentAccountId uniqueidentifier NOT NULL REFERENCES dbo.CorrespondentAccounts(CorrespondentAccountId),FromAmount decimal(19,4) NOT NULL,ExchangeRate decimal(19,8) NOT NULL,ToAmount AS CAST(FromAmount*ExchangeRate AS decimal(19,4)) PERSISTED,ReferenceNo nvarchar(100) NULL,Narration nvarchar(500) NULL,TransactionDate datetime2 NOT NULL,CreatedTime datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CreatedBy nvarchar(100) NULL,DeletedTime datetime2 NULL,DeletedBy nvarchar(100) NULL,CONSTRAINT CK_Deals_Values CHECK(FromAmount>0 AND ExchangeRate>0),CONSTRAINT CK_Deals_Accounts CHECK(FromCorrespondentAccountId<>ToCorrespondentAccountId));
IF OBJECT_ID('dbo.ExchangeRates') IS NULL CREATE TABLE dbo.ExchangeRates(ExchangeRateId uniqueidentifier NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,RateDate date NOT NULL,FromCurrencyId uniqueidentifier NOT NULL REFERENCES dbo.Currencies(CurrencyId),ToCurrencyId uniqueidentifier NOT NULL REFERENCES dbo.Currencies(CurrencyId),RateValue decimal(19,8) NOT NULL,CreatedTime datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CreatedBy nvarchar(100) NULL,DeletedTime datetime2 NULL,DeletedBy nvarchar(100) NULL,CONSTRAINT UQ_ExchangeRates UNIQUE(RateDate,FromCurrencyId,ToCurrencyId),CONSTRAINT CK_ExchangeRates CHECK(RateValue>0 AND FromCurrencyId<>ToCurrencyId));
IF OBJECT_ID('dbo.ReserveSnapshots') IS NULL CREATE TABLE dbo.ReserveSnapshots(ReserveSnapshotId uniqueidentifier NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,ReserveDate date NOT NULL,GoldValue decimal(19,4) NOT NULL DEFAULT 0,CashInHand decimal(19,4) NOT NULL DEFAULT 0,Deposits decimal(19,4) NOT NULL DEFAULT 0,Notes nvarchar(500) NULL,CreatedTime datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CreatedBy nvarchar(100) NULL,DeletedTime datetime2 NULL,DeletedBy nvarchar(100) NULL,CONSTRAINT CK_ReserveSnapshots CHECK(GoldValue>=0 AND CashInHand>=0 AND Deposits>=0 AND GoldValue+CashInHand+Deposits>0));
IF OBJECT_ID('dbo.Obligations') IS NULL CREATE TABLE dbo.Obligations(ObligationId uniqueidentifier NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,ObligationDate date NOT NULL,ClientName nvarchar(200) NOT NULL,CurrencyId uniqueidentifier NOT NULL REFERENCES dbo.Currencies(CurrencyId),TotalAmount decimal(19,4) NOT NULL,PaidAmount decimal(19,4) NOT NULL DEFAULT 0,DueDate date NULL,ReferenceNo nvarchar(100) NULL,Notes nvarchar(500) NULL,IsActive bit NOT NULL DEFAULT 1,CreatedTime datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CreatedBy nvarchar(100) NULL,DeletedTime datetime2 NULL,DeletedBy nvarchar(100) NULL,CONSTRAINT CK_Obligations CHECK(TotalAmount>0 AND PaidAmount>=0 AND PaidAmount<=TotalAmount));
IF OBJECT_ID('dbo.ObligationPayments') IS NULL CREATE TABLE dbo.ObligationPayments(ObligationPaymentId uniqueidentifier NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,ObligationId uniqueidentifier NOT NULL REFERENCES dbo.Obligations(ObligationId),CorrespondentAccountId uniqueidentifier NOT NULL REFERENCES dbo.CorrespondentAccounts(CorrespondentAccountId),PaymentDate date NOT NULL,Amount decimal(19,4) NOT NULL,ReferenceNo nvarchar(100) NULL,Notes nvarchar(500) NULL,CreatedTime datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CreatedBy nvarchar(100) NULL,DeletedTime datetime2 NULL,DeletedBy nvarchar(100) NULL,CONSTRAINT CK_ObligationPayments CHECK(Amount>0));
/* Upgrade the earlier API schema in place. These renames preserve data. */
IF COL_LENGTH('dbo.Currencies','CurrencyCode') IS NULL AND COL_LENGTH('dbo.Currencies','code') IS NOT NULL EXEC sp_rename 'dbo.Currencies.code','CurrencyCode','COLUMN';
IF EXISTS(SELECT 1 FROM sys.columns c JOIN sys.types t ON t.user_type_id=c.user_type_id WHERE c.object_id=OBJECT_ID('dbo.Currencies')AND c.name='CurrencyCode'AND t.name='bigint') BEGIN DECLARE @currencyConstraint sysname;SELECT TOP(1)@currencyConstraint=kc.name FROM sys.key_constraints kc JOIN sys.index_columns ic ON ic.object_id=kc.parent_object_id AND ic.index_id=kc.unique_index_id JOIN sys.columns c ON c.object_id=ic.object_id AND c.column_id=ic.column_id WHERE kc.parent_object_id=OBJECT_ID('dbo.Currencies')AND c.name='CurrencyCode';IF @currencyConstraint IS NOT NULL EXEC('ALTER TABLE dbo.Currencies DROP CONSTRAINT ['+@currencyConstraint+']');ALTER TABLE dbo.Currencies ALTER COLUMN CurrencyCode nvarchar(3) NOT NULL;ALTER TABLE dbo.Currencies ADD CONSTRAINT UQ_Currencies_CurrencyCode UNIQUE(CurrencyCode);END;
IF COL_LENGTH('dbo.Currencies','CurrencyNameEn') IS NULL AND COL_LENGTH('dbo.Currencies','nameEn') IS NOT NULL EXEC sp_rename 'dbo.Currencies.nameEn','CurrencyNameEn','COLUMN';
IF COL_LENGTH('dbo.Currencies','CurrencyNameAr') IS NULL AND COL_LENGTH('dbo.Currencies','nameAr') IS NOT NULL EXEC sp_rename 'dbo.Currencies.nameAr','CurrencyNameAr','COLUMN';
IF COL_LENGTH('dbo.Beneficiaries','BeneficiaryCode') IS NULL BEGIN ALTER TABLE dbo.Beneficiaries ADD BeneficiaryCode nvarchar(50) NULL;EXEC('UPDATE dbo.Beneficiaries SET BeneficiaryCode=''BEN-''+LEFT(CONVERT(varchar(36),BeneficiaryId),20) WHERE BeneficiaryCode IS NULL');END;
IF COL_LENGTH('dbo.Correspondents','CorrespondentCode') IS NULL AND COL_LENGTH('dbo.Correspondents','swiftCode') IS NOT NULL EXEC sp_rename 'dbo.Correspondents.swiftCode','CorrespondentCode','COLUMN';
IF COL_LENGTH('dbo.CorrespondentAccounts','CurrentBalance') IS NULL BEGIN ALTER TABLE dbo.CorrespondentAccounts ADD CurrentBalance decimal(19,4) NULL;EXEC('UPDATE dbo.CorrespondentAccounts SET CurrentBalance=OpeningBalance WHERE CurrentBalance IS NULL');END;
IF COL_LENGTH('dbo.ResourceTypes','ResourceTypeCode') IS NULL AND COL_LENGTH('dbo.ResourceTypes','typeCode') IS NOT NULL EXEC sp_rename 'dbo.ResourceTypes.typeCode','ResourceTypeCode','COLUMN';
IF COL_LENGTH('dbo.ResourceTypes','ResourceTypeNameEn') IS NULL AND COL_LENGTH('dbo.ResourceTypes','typeNameEn') IS NOT NULL EXEC sp_rename 'dbo.ResourceTypes.typeNameEn','ResourceTypeNameEn','COLUMN';
IF COL_LENGTH('dbo.ResourceTypes','ResourceTypeNameAr') IS NULL AND COL_LENGTH('dbo.ResourceTypes','typeNameAr') IS NOT NULL EXEC sp_rename 'dbo.ResourceTypes.typeNameAr','ResourceTypeNameAr','COLUMN';
IF COL_LENGTH('dbo.OperationTypes','OperationTypeCode') IS NULL BEGIN ALTER TABLE dbo.OperationTypes ADD OperationTypeCode nvarchar(50) NULL;EXEC('UPDATE dbo.OperationTypes SET OperationTypeCode=CONVERT(nvarchar(50),operationCode) WHERE OperationTypeCode IS NULL');END;
IF COL_LENGTH('dbo.OperationTypes','OperationTypeNameEn') IS NULL AND COL_LENGTH('dbo.OperationTypes','operationNameEn') IS NOT NULL EXEC sp_rename 'dbo.OperationTypes.operationNameEn','OperationTypeNameEn','COLUMN';
IF COL_LENGTH('dbo.UsageTypes','UsageTypeCode') IS NULL BEGIN ALTER TABLE dbo.UsageTypes ADD UsageTypeCode nvarchar(50) NULL;EXEC('UPDATE dbo.UsageTypes SET UsageTypeCode=CONVERT(nvarchar(50),typeCode) WHERE UsageTypeCode IS NULL');END;
IF COL_LENGTH('dbo.UsageTypes','UsageTypeNameEn') IS NULL AND COL_LENGTH('dbo.UsageTypes','typeNameEn') IS NOT NULL EXEC sp_rename 'dbo.UsageTypes.typeNameEn','UsageTypeNameEn','COLUMN';
IF COL_LENGTH('dbo.Coverages','FromCorrespondentAccountId') IS NULL AND COL_LENGTH('dbo.Coverages','fromAccountId') IS NOT NULL EXEC sp_rename 'dbo.Coverages.fromAccountId','FromCorrespondentAccountId','COLUMN';
IF COL_LENGTH('dbo.Coverages','ToCorrespondentAccountId') IS NULL AND COL_LENGTH('dbo.Coverages','toAccountId') IS NOT NULL EXEC sp_rename 'dbo.Coverages.toAccountId','ToCorrespondentAccountId','COLUMN';
IF COL_LENGTH('dbo.Coverages','TransactionDate') IS NULL AND COL_LENGTH('dbo.Coverages','coverageDate') IS NOT NULL EXEC sp_rename 'dbo.Coverages.coverageDate','TransactionDate','COLUMN';
IF COL_LENGTH('dbo.Coverages','Narration') IS NULL AND COL_LENGTH('dbo.Coverages','reason') IS NOT NULL EXEC sp_rename 'dbo.Coverages.reason','Narration','COLUMN';
IF COL_LENGTH('dbo.Obligations','DueDate') IS NULL ALTER TABLE dbo.Obligations ADD DueDate date NULL;
IF COL_LENGTH('dbo.Obligations','ReferenceNo') IS NULL ALTER TABLE dbo.Obligations ADD ReferenceNo nvarchar(100) NULL;
IF COL_LENGTH('dbo.ObligationPayments','CorrespondentAccountId') IS NULL ALTER TABLE dbo.ObligationPayments ADD CorrespondentAccountId uniqueidentifier NULL;
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID('dbo.Transfers')AND name='IX_Transfers_AccountDate') CREATE INDEX IX_Transfers_AccountDate ON dbo.Transfers(CorrespondentAccountId,TransferDate) INCLUDE(Amount,TransferStatus) WHERE DeletedTime IS NULL;
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID('dbo.Resources')AND name='IX_Resources_AccountDate') CREATE INDEX IX_Resources_AccountDate ON dbo.Resources(CorrespondentAccountId,ResourceDate) INCLUDE(Amount) WHERE DeletedTime IS NULL;
COMMIT;
